## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/atopicDermatitisLogic.ts`

```typescript
/**
 * Atopic Dermatitis Clinical Logic Engine
 *
 * Based on:
 * - AAD 2025 Focused Update: Tapinarof, Roflumilast, Lebrikizumab, Nemolizumab
 *   (PMID: 40531067)
 * - AAD 2023 Guidelines: Phototherapy and Systemic Therapies
 *   (PMID: 37943241, PMID: 38108679)
 * - AAD 2026 Systemic Therapy Refinement (JAK inhibitors vs biologics)
 * - SOLO 1 & SOLO 2 Dupilumab Trials (PMID: 27760005)
 * - Dupilumab in ages 6-12 (PMID: 33007469)
 */

export type ADSeverity = "mild" | "moderate" | "severe";
export type AgeGroup = "adult" | "adolescent_12_17" | "child_6_11" | "child_6mo_5yr";
export type FailedTherapy = "none" | "topicals_only" | "topicals_and_phototherapy" | "prior_biologic" | "prior_jak";

export interface AtopicDermatitisInput {
  // Severity scoring
  igaScore: 0 | 1 | 2 | 3 | 4; // 0=clear, 1=almost clear, 2=mild, 3=moderate, 4=severe
  easiScore: number; // 0-72
  bsaPercent: number; // 0-100
  pruritusNrs: number; // 0-10 numeric rating scale

  // Patient demographics
  ageGroup: AgeGroup;

  // Prior treatment history
  failedTherapy: FailedTherapy;

  // Comorbidities and risk factors
  hasOcularDisease: boolean; // conjunctivitis, keratitis — affects biologic choice
  hasCardiovascularRisk: boolean; // MACE risk — affects JAK inhibitor eligibility
  hasThromboembolismHistory: boolean; // DVT/PE — JAK inhibitor boxed warning
  hasMalignancyHistory: boolean; // JAK inhibitor boxed warning
  isPregnantOrPlanning: boolean;
  isImmunocompromised: boolean;

  // Special considerations
  hasSignificantPruritus: boolean; // NRS >= 7 — nemolizumab pathway
  hasEczemaHerpeticum: boolean; // urgent: antiviral first
  hasBacterialSuperinfection: boolean; // urgent: antibiotics first
  hasContactAllergyConfirmed: boolean; // patch testing done
}

export interface ADRecommendation {
  severity: ADSeverity;
  primaryRecommendation: string;
  treatmentPathway: string;
  specificAgents: string[];
  agentsToAvoid: string[];
  monitoringPlan: string[];
  urgentFlags: string[];
  nextSteps: string[];
  evidenceLevel: string;
  references: Array<{ citation: string; pmid?: string; url?: string }>;
  sharedDecisionPoints: string[];
}

function classifySeverity(input: AtopicDermatitisInput): ADSeverity {
  // IGA-based primary classification
  if (input.igaScore <= 1) return "mild";
  if (input.igaScore === 2) return "mild";
  if (input.igaScore === 3) return "moderate";
  if (input.igaScore === 4) return "severe";

  // EASI-based fallback
  if (input.easiScore < 7) return "mild";
  if (input.easiScore < 21) return "moderate";
  return "severe";
}

export function assessAtopicDermatitis(input: AtopicDermatitisInput): ADRecommendation {
  const severity = classifySeverity(input);

  const urgentFlags: string[] = [];
  const specificAgents: string[] = [];
  const agentsToAvoid: string[] = [];
  const nextSteps: string[] = [];
  const monitoringPlan: string[] = [];
  const sharedDecisionPoints: string[] = [];

  // Urgent flags
  if (input.hasEczemaHerpeticum) {
    urgentFlags.push("URGENT: Eczema herpeticum suspected — initiate systemic acyclovir/valacyclovir immediately before advancing AD therapy");
  }
  if (input.hasBacterialSuperinfection) {
    urgentFlags.push("URGENT: Bacterial superinfection (S. aureus) — treat with appropriate antibiotics before escalating AD therapy");
  }

  // Contraindication flags
  if (input.hasCardiovascularRisk || input.hasThromboembolismHistory || input.hasMalignancyHistory) {
    agentsToAvoid.push("JAK inhibitors (upadacitinib, abrocitinib, baricitinib) — FDA Boxed Warning: increased risk of MACE, thromboembolism, and malignancy");
  }
  if (input.isPregnantOrPlanning) {
    agentsToAvoid.push("JAK inhibitors — contraindicated in pregnancy");
    agentsToAvoid.push("Systemic immunosuppressants (cyclosporine, methotrexate) — teratogenic");
    sharedDecisionPoints.push("Dupilumab has the most safety data in pregnancy; discuss risk-benefit with patient");
  }

  let primaryRecommendation = "";
  let treatmentPathway = "";
  let evidenceLevel = "";

  if (severity === "mild") {
    primaryRecommendation = "Topical therapy with non-steroidal agents preferred for long-term management";
    treatmentPathway =
      "Step 1: Optimize skincare baseline (fragrance-free emollients, lukewarm bathing, trigger avoidance). " +
      "Step 2: Topical corticosteroids (TCS) for acute flares — lowest effective potency. " +
      "Step 3: Non-steroidal topicals for maintenance: roflumilast cream 0.15% (PDE-4i, IGA 2-3) or crisaborole 2% ointment (ages ≥3 months). " +
      "Step 4: Topical calcineurin inhibitors (pimecrolimus 1% cream) for sensitive areas (face, intertriginous).";

    specificAgents.push("Roflumilast cream 0.15% once daily — AAD 2025 strong recommendation for mild-moderate AD (IGA 2-3)");
    specificAgents.push("Crisaborole 2% ointment — FDA approved ≥3 months; mild-moderate AD");
    specificAgents.push("Pimecrolimus 1% cream — face, eyelids, intertriginous areas");
    specificAgents.push("Ruxolitinib 1.5% cream — mild-moderate AD, ages ≥12");
    specificAgents.push("Tapinarof cream 1% — AhR agonist; approved mild-severe AD (once daily, 'remittive effect')");

    monitoringPlan.push("Reassess IGA and NRS at 4-8 weeks");
    monitoringPlan.push("Escalate if no response to topicals after 4-6 weeks");
    evidenceLevel = "Strong recommendation (AAD 2025, Level A)";

  } else if (severity === "moderate") {
    primaryRecommendation = "Escalate to biologic or JAK inhibitor if topicals and phototherapy insufficient";
    treatmentPathway =
      "Step 1: Optimize topical regimen (TCS + non-steroidal topicals). " +
      "Step 2: Phototherapy (narrowband UVB) if topicals inadequate. " +
      "Step 3: Biologic therapy — dupilumab (IL-4Rα, ages ≥6 months), tralokinumab (IL-13, ages ≥12), lebrikizumab (IL-13, adults), nemolizumab (IL-31Rα, ages ≥12 with significant pruritus). " +
      "Step 4: JAK inhibitors if no CV/thromboembolism/malignancy risk — upadacitinib, abrocitinib, baricitinib.";

    if (input.hasOcularDisease) {
      specificAgents.push("Nemolizumab (IL-31Rα) — preferred over IL-4/13 biologics in patients with ocular comorbidity (conjunctivitis)");
      specificAgents.push("JAK inhibitor (if no CV risk) — upadacitinib or abrocitinib");
      agentsToAvoid.push("Dupilumab, tralokinumab, lebrikizumab — may worsen conjunctivitis in patients with pre-existing ocular disease");
    } else if (input.hasSignificantPruritus && input.pruritusNrs >= 7) {
      specificAgents.push("Nemolizumab (IL-31Rα, SC monthly) — specifically targets IL-31-mediated pruritus; AAD 2025 strong recommendation for ages ≥12");
      specificAgents.push("Dupilumab (IL-4Rα) — first-line biologic, broadest age approval (≥6 months)");
    } else {
      specificAgents.push("Dupilumab (IL-4Rα) — first-line biologic; strong recommendation AAD 2025; ages ≥6 months");
      specificAgents.push("Lebrikizumab (IL-13) — AAD 2025 strong recommendation; adults; Q2W then Q4W maintenance");
      specificAgents.push("Tralokinumab (IL-13) — AAD 2023 strong recommendation; ages ≥12");
    }

    if (!input.hasCardiovascularRisk && !input.hasThromboembolismHistory && !input.hasMalignancyHistory) {
      specificAgents.push("Upadacitinib 15mg or 30mg daily — JAK1 inhibitor; strong recommendation AAD 2026");
      specificAgents.push("Abrocitinib 100mg or 200mg daily — JAK1 inhibitor; strong recommendation AAD 2026");
      specificAgents.push("Baricitinib 2mg or 4mg daily — JAK1/2 inhibitor; strong recommendation AAD 2026");
    }

    monitoringPlan.push("Reassess EASI and IGA at 16 weeks (biologic) or 12 weeks (JAK inhibitor)");
    monitoringPlan.push("Monitor for injection site reactions, conjunctivitis (dupilumab/tralokinumab/lebrikizumab)");
    monitoringPlan.push("JAK inhibitors: CBC, lipids, LFTs at baseline and periodically; screen for TB and hepatitis B");
    evidenceLevel = "Strong recommendation (AAD 2025/2026, Level A)";

  } else {
    // Severe
    primaryRecommendation = "Biologic or JAK inhibitor therapy required; consider combination with topicals";
    treatmentPathway =
      "Step 1: Initiate biologic therapy — dupilumab preferred first-line (broadest evidence, all ages ≥6 months). " +
      "Step 2: Alternative biologics: lebrikizumab, tralokinumab, nemolizumab (pruritus-dominant). " +
      "Step 3: JAK inhibitors (if no CV/thromboembolism/malignancy risk): upadacitinib 30mg, abrocitinib 200mg. " +
      "Step 4: Short-course systemic corticosteroids only as bridge — not for maintenance (AAD strongly recommends against). " +
      "Step 5: Phototherapy adjunct for recalcitrant disease.";

    if (input.hasOcularDisease) {
      specificAgents.push("Nemolizumab — preferred in ocular comorbidity; avoids IL-4/13 pathway");
      if (!input.hasCardiovascularRisk && !input.hasThromboembolismHistory && !input.hasMalignancyHistory) {
        specificAgents.push("Upadacitinib 30mg daily — highest efficacy JAK inhibitor for severe AD");
      }
    } else {
      specificAgents.push("Dupilumab — first-line; 300mg Q2W (adults); weight-based dosing in children");
      specificAgents.push("Lebrikizumab — 500mg Q2W x2 loading, then 250mg Q2W, then 250mg Q4W maintenance");
      specificAgents.push("Tralokinumab — 600mg loading, then 300mg Q2W");
      if (!input.hasCardiovascularRisk && !input.hasThromboembolismHistory && !input.hasMalignancyHistory) {
        specificAgents.push("Upadacitinib 30mg daily — JAK1 inhibitor; highest EASI-75 rates in head-to-head vs dupilumab");
        specificAgents.push("Abrocitinib 200mg daily — JAK1 inhibitor");
      }
    }

    agentsToAvoid.push("Long-term systemic corticosteroids — strongly recommended against by AAD");
    agentsToAvoid.push("Cyclosporine — short-term bridge only; not for maintenance");

    monitoringPlan.push("Reassess EASI, IGA, and pruritus NRS at 16 weeks");
    monitoringPlan.push("If inadequate response at 16 weeks: switch biologic class or add JAK inhibitor");
    monitoringPlan.push("JAK inhibitors: CBC, lipids, LFTs, TB screening, hepatitis B at baseline");
    monitoringPlan.push("Annual skin cancer surveillance on JAK inhibitors");
    evidenceLevel = "Strong recommendation (AAD 2025/2026, Level A)";
  }

  // Age-specific adjustments
  if (input.ageGroup === "child_6mo_5yr") {
    nextSteps.push("Age ≥6 months: dupilumab is the only approved biologic; weight-based dosing");
    nextSteps.push("Crisaborole 2% ointment approved ≥3 months for mild-moderate AD");
    nextSteps.push("Avoid JAK inhibitors — not approved in this age group");
  } else if (input.ageGroup === "child_6_11") {
    nextSteps.push("Age 6-11: dupilumab approved (PMID: 33007469); IGA=4, EASI≥21, NRS≥4, BSA≥15% criteria");
    nextSteps.push("Crisaborole and pimecrolimus available for mild-moderate disease");
  } else if (input.ageGroup === "adolescent_12_17") {
    nextSteps.push("Age 12-17: dupilumab, tralokinumab, nemolizumab, abrocitinib, upadacitinib all approved");
    nextSteps.push("Ruxolitinib 1.5% cream approved for mild-moderate AD ages ≥12");
  }

  // Prior treatment failure adjustments
  if (input.failedTherapy === "prior_biologic") {
    nextSteps.push("Prior biologic failure: switch biologic class (e.g., IL-4Rα → IL-13 or IL-31Rα) or escalate to JAK inhibitor");
    sharedDecisionPoints.push("Discuss mechanism of action differences between biologic classes; JAK inhibitors may achieve faster response");
  }
  if (input.failedTherapy === "prior_jak") {
    nextSteps.push("Prior JAK inhibitor failure: switch to biologic; consider combination therapy with topical non-steroidal agents");
  }

  // Universal next steps
  nextSteps.push("Confirm diagnosis: patch testing if contact allergy suspected");
  nextSteps.push("Optimize emollient regimen: apply within 3 minutes of bathing ('soak and smear')");
  nextSteps.push("Assess and address psychosocial burden (DLQI, PHQ-9)");
  nextSteps.push("Refer to dermatology if not responding to step 2 therapy");

  sharedDecisionPoints.push("Route of administration: biologics (SC injection) vs oral JAK inhibitors — patient preference matters");
  sharedDecisionPoints.push("Pregnancy planning: dupilumab has most safety data; JAK inhibitors contraindicated");
  sharedDecisionPoints.push("Cost and insurance: prior authorization typically required for biologics and JAK inhibitors");

  return {
    severity,
    primaryRecommendation,
    treatmentPathway,
    specificAgents,
    agentsToAvoid,
    monitoringPlan,
    urgentFlags,
    nextSteps,
    evidenceLevel,
    sharedDecisionPoints,
    references: [
      {
        citation: "AAD 2025 Focused Update: Tapinarof, Roflumilast, Lebrikizumab, Nemolizumab for Atopic Dermatitis",
        pmid: "40531067",
        url: "https://pubmed.ncbi.nlm.nih.gov/40531067/",
      },
      {
        citation: "AAD 2023 Guidelines: Phototherapy and Systemic Therapies for AD",
        pmid: "37943241",
        url: "https://pubmed.ncbi.nlm.nih.gov/37943241/",
      },
      {
        citation: "AAD 2023 Guidelines: Systemic Therapies Part 2",
        pmid: "38108679",
        url: "https://pubmed.ncbi.nlm.nih.gov/38108679/",
      },
      {
        citation: "Dupilumab SOLO 1 & SOLO 2 Trials — Simpson EL et al., NEJM 2016",
        pmid: "27760005",
        url: "https://pubmed.ncbi.nlm.nih.gov/27760005/",
      },
      {
        citation: "Dupilumab in Patients Aged 6-12 Years — Cork MJ et al., NEJM 2021",
        pmid: "33007469",
        url: "https://pubmed.ncbi.nlm.nih.gov/33007469/",
      },
      {
        citation: "AAD 2023 Guidelines Highlights — Silverberg JI et al.",
        pmid: "39251015",
        url: "https://pubmed.ncbi.nlm.nih.gov/39251015/",
      },
    ],
  };
}

export function getADSeverityColor(severity: ADSeverity): string {
  switch (severity) {
    case "mild": return "text-green-700 bg-green-50 border-green-200";
    case "moderate": return "text-amber-700 bg-amber-50 border-amber-200";
    case "severe": return "text-red-700 bg-red-50 border-red-200";
  }
}

export function getADSeverityBadge(severity: ADSeverity): string {
  switch (severity) {
    case "mild": return "Mild AD";
    case "moderate": return "Moderate AD";
    case "severe": return "Severe AD";
  }
}
